  set: function(header, valueOrRewrite, rewrite) {
    const self = this;
    const pendingEntries = [];
    const objectTag = Object.prototype.toString;
    const boundPush = bind(pendingEntries.push, pendingEntries);
    let rewriteFlag = rewrite;
    let isHeaderMap = false;

    if (header != null) {
      if (typeof header === 'object') {
        const headerTag = objectTag.call(header);
        if (headerTag === '[object Object]') {
          const headerProto = Object.getPrototypeOf(header);
          const objectProto = Object.prototype;
          const parentProto = headerProto ? Object.getPrototypeOf(headerProto) : null;
